using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class SeatMountainMarkings {
 public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/MountainLoopReverse.unity");var b=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title=="Summit Traverse");var pavement=GameObject.Find("Ground_CR133 mountain driving surface").GetComponent<Collider>();int count=0;foreach(var mf in Object.FindObjectsByType<MeshFilter>().Where(m=>m.sharedMesh&&(m.name.Contains("arrow")||m.name.Contains("Main teal")||m.name.Contains("Optional gold")))){var v=mf.sharedMesh.vertices;bool changed=false;for(int i=0;i<v.Length;i++){var p=mf.transform.TransformPoint(v[i]);float s=b.Project(p,out float d);if(s<365||s>460||d>10)continue;if(pavement.Raycast(new Ray(p+Vector3.up*8,Vector3.down),out var h,16)){p.y=h.point.y+.06f;v[i]=mf.transform.InverseTransformPoint(p);count++;changed=true;}}if(!changed)continue;var mesh=Object.Instantiate(mf.sharedMesh);mesh.vertices=v;mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,AssetDatabase.GenerateUniqueAssetPath("Assets/Track/MountainPolish/marking-"+mf.name.Replace('/','-')+".asset"));mf.sharedMesh=mesh;}
 EditorSceneManager.MarkSceneDirty(b.gameObject.scene);EditorSceneManager.SaveScene(b.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/MountainPolish/markings.txt","Final surface marking vertices seated above pavement="+count);return "Marking vertices="+count;}
}
